// SPDX-License-Identifier: GPL-2.0-or-later
// Generator for the EVGA USB module device table.
// Usage: node scripts/openrgb/port-evga-usb-devices.mjs <openrgb-root> <commit>
// Reads Controllers/EVGAUSBController/{EVGAKeyboardControllerDetect,
// EVGAMouseControllerDetect,EVGAX12ControllerDetect}.cpp and regenerates
// modules/evga-usb/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'EVGAUSBController');
const read = (rel) => fs.readFileSync(path.join(family, rel), 'utf8');
const sources = [
  path.join('EVGAKeyboardController', 'EVGAKeyboardControllerDetect.cpp'),
  path.join('EVGAMouseController', 'EVGAMouseControllerDetect.cpp'),
  path.join('EVGAX12Controller', 'EVGAX12ControllerDetect.cpp'),
];
const detect = sources.map(read).join('\n');
// EVGA_X12_* constants live in the .h files, so defines are resolved from all sources
const headerText = fs
  .readdirSync(family, { recursive: true })
  .filter((f) => /\.(cpp|h)$/.test(f))
  .map((f) => fs.readFileSync(path.join(family, f), 'utf8'))
  .join('\n');

const constants = Object.fromEntries(
  [...headerText.matchAll(/#define\s+([A-Z][A-Z0-9_]*)\s+(0x[0-9A-Fa-f]+|\d+)/g)].map((m) => [
    m[1],
    m[2].startsWith('0x') ? Number.parseInt(m[2], 16) : Number.parseInt(m[2], 10),
  ]),
);
if (constants.EVGA_USB_VID == null) throw new Error('EVGA_USB_VID not found');
const n = (s) => {
  const t = s.trim();
  if (t in constants) return constants[t];
  if (/^0x[0-9A-Fa-f]+$/.test(t)) return Number.parseInt(t, 16);
  if (/^\d+$/.test(t)) return Number.parseInt(t, 10);
  throw new Error(`unresolved constant ${t}`);
};

// The two wireless detector rows belong to a receiver (X20 adapter); the wired
// mouse rows and the X12 share the peripheral packet protocol with reads.
const protocol = (m) => {
  if (m[2] === 'DetectEVGAX12') return 'x12';
  if (m[2] === 'DetectWiredEVGAMouse') return 'mouse';
  if (m[2] === 'DetectWirelessEVGAMouse') return 'wireless';
  return 'keyboard';
};

const rows = [];
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR_IPU\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*EVGA_USB_VID\s*,\s*([A-Z][A-Z0-9_]+)\s*,\s*([A-Z][A-Z0-9_]+|\d+)\s*,\s*([A-Z][A-Z0-9_]+|0x[0-9A-Fa-f]+|\d+)\s*,\s*([A-Z][A-Z0-9_]+|0x[0-9A-Fa-f]+|\d+)\s*\)/g,
)) {
  const pid = n(m[3]);
  if (!Number.isFinite(pid)) throw new Error(`unresolved PID ${m[3]} in row ${m[1]}`);
  const page = n(m[5]);
  const usage = n(m[6]);
  const iface = n(m[4]);
  if (!Number.isFinite(page) || !Number.isFinite(usage) || !Number.isFinite(iface)) {
    throw new Error(`unresolved detector args ${JSON.stringify(m.slice(4))} in row ${m[1]}`);
  }
  rows.push({
    name: m[1],
    handler: m[2],
    vid: constants.EVGA_USB_VID,
    pid,
    interface: iface,
    usagePage: page,
    usage,
    protocol: protocol(m),
  });
}
if (rows.length !== 7) throw new Error(`expected 7 detector rows, got ${rows.length}`);

const out = path.join(process.cwd(), 'modules', 'evga-usb', 'src', 'devices_table.rs');
fs.mkdirSync(path.dirname(out), { recursive: true });
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-evga-usb-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::Detector;',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map((d) =>
    `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, interface: ${d.interface}, usage_page: 0x${d.usagePage.toString(16)}, usage: 0x${d.usage.toString(16)}, protocol: ${JSON.stringify(d.protocol)} },`,
  ),
  '];',
  '',
];
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} EVGA USB HID detectors`);